TEST(EmitExpr, GenWithLnext) {
    // Optional 4th gen() arg.
    std::vector<std::string> errs;
    auto t = emit_with_body("cg_x(x);", errs);
    (void)t;
    auto t2 = emit_with_body(
        "label L;\n"
        "let lk = gen(l, effect, fail, L);\n"
        "cg_x(lk);", errs);
    // Body references `l` which only exists in the Add rule; this
    // emit_with_body slots it into the `lit` rule which doesn't have l
    // — intentional, expect a typecheck error rather than a malformed
    // emission. The "only exists in Add" gap is checked elsewhere.
    EXPECT_TRUE(t2.empty() || t2.find("compile_expr(l, effect(),") != std::string::npos);
}

