TEST(Destinations, DestVariantArityChecked) {
    // `restore` is declared with one int payload; calling with zero
    // args is a real error, not a silent miss.
    static const char* src = R"(
COMPILER hello
IMPORTS
  ast = "ast.json"
DESTINATIONS
  data_dest delta { effect }
  ctrl_dest gamma { fail | restore(save: int) }
  ir_root int
AUXILIARIES
  cg_x : (int) -> int
RULES
rule lit : ast.Lit(n: x) { cg_x(x); }
rule add : ast.Add(left: l, right: r) {
    let lk = gen(l, effect, restore);
    cg_x(lk);
}
)";
    auto* file = parse_ddcg(src);
    ASSERT_NE(file, nullptr);
    std::map<std::string, Schema> schemas{{"ast", make_tiny_schema()}};
    auto r = check_file(file, schemas);
    EXPECT_FALSE(r.ok());
    // `restore` referenced as a bare ident is treated as a 0-arg dest
    // call but the variant declares one int payload — gen's γ slot
    // ends up with a type that doesn't match the ctrl_dest's expected
    // shape, OR a flat arity error from infer_call. Either way: error.
    bool got = has_err_substring(r, "expects 1 arg") ||
               has_err_substring(r, "control destination");
    EXPECT_TRUE(got)
        << "expected arity or dest-type error; first error: "
        << (r.errors.empty() ? "(none)" : r.errors.front().message);
}

