TEST(Codegen, WhereGuardCallsPredicateAsBareMember) {
    // PREDICATES are declared at DSL level and the user provides their
    // bodies inside MEMBERS. The where-guard call site emits a bare
    // call — `this` is implicit inside the dispatcher method.
    static const char* src = R"(
COMPILER guarded
IMPORTS
  ast = "ast.json"
DESTINATIONS
  data_dest delta { effect }
  ctrl_dest gamma { fail }
  ir_root int
AUXILIARIES
  cg_x : (int) -> int
PREDICATES
  is_pos : (int) -> bool
RULES
rule lit_pos : ast.Lit(n: x) where is_pos(x) { cg_x(x); }
rule lit     : ast.Lit(n: x)                 { cg_x(x); }
rule add     : ast.Add(left: l, right: r) {
    let lk = gen(l, effect, fail);
    cg_x(lk);
}
)";
    auto* file = parse_ddcg(src);
    ASSERT_NE(file, nullptr);
    std::map<std::string, Schema> schemas{{"ast", make_tiny_schema()}};
    auto check = check_file(file, schemas);
    ASSERT_TRUE(check.ok())
        << (check.errors.empty() ? "" : check.errors.front().message);

    std::ostringstream out;
    std::vector<std::string> emit_errs;
    ASSERT_TRUE(emit_cpp(file, schemas, check, out, emit_errs));
    std::string text = out.str();
    EXPECT_NE(text.find("if (is_pos(x))"), std::string::npos)
        << "where-guard predicate must be called as a bare member call:\n" << text;
}

