TEST(Destinations, MultiVariantDataDestRoundTripsThroughCodegen) {
    // The whole point: a non-trivial δ. Confirm a Location-style
    // data_dest with multiple variants (effect | ac | stack(slot: int))
    // type-checks AND its variant constructors emit correctly in the
    // generated dispatcher (zero-arg variants as `name()`, payload
    // variants as `name(args)`).
    static const char* src = R"(
COMPILER multi
IMPORTS
  ast = "ast.json"
DESTINATIONS
  data_dest delta { effect | ac | stack(slot: int) }
  ctrl_dest gamma { fail }
  ir_root int
AUXILIARIES
  cg_x : (int) -> int
RULES
rule lit : ast.Lit(n: x) { cg_x(x); }
rule add : ast.Add(left: l, right: r) {
    let lk = gen(l, ac, fail);
    let rk = gen(r, stack(0), fail);
    cg_x(lk + rk);
}
)";
    auto* file = parse_ddcg(src);
    ASSERT_NE(file, nullptr);
    std::map<std::string, Schema> schemas{{"ast", make_tiny_schema()}};
    auto check = check_file(file, schemas);
    ASSERT_TRUE(check.ok())
        << (check.errors.empty() ? "" : check.errors.front().message);

    std::ostringstream out;
    std::vector<std::string> emit_errs;
    ASSERT_TRUE(emit_cpp(file, schemas, check, out, emit_errs))
        << (emit_errs.empty() ? "" : emit_errs.front());
    std::string text = out.str();

    // Bare 0-arg ident `ac` → `ac()` constructor call.
    EXPECT_NE(text.find("ac()"), std::string::npos)
        << "0-arg dest variant should emit as `name()`:\n" << text;
    // Payload variant emits as a real call with the payload.
    EXPECT_NE(text.find("stack(0)"), std::string::npos)
        << "payload dest variant should preserve args:\n" << text;
    // Dispatcher signature has both.
    EXPECT_NE(text.find("delta_t d, gamma_t g)"), std::string::npos)
        << "dispatcher signature missing one of δ/γ:\n" << text;
}

// ─── Codegen tests ──────────────────────────────────────────────
//
// Round-trip a .ddcg through parse → typecheck → emit_cpp and inspect
// the emitted text for the structural properties we care about. We're
// not pinning literal output; we're checking the emitter consumed the
// type-checker's side-table correctly.

namespace {

Schema make_two_sum_schema() {
    // module: ast
    //   sum expr = Lit(int n) | EVar(stmt body)        // expr that contains a stmt
    //   sum stmt = SExpr(expr e) | SSeq(stmt next)     // stmt that contains an expr
    Schema s;
    s.module_name = "ast";
    s.sum_names.insert("expr");
    s.sum_names.insert("stmt");
    s.sum_constructors["expr"] = {"Lit", "EVar"};
    s.sum_constructors["stmt"] = {"SExpr", "SSeq"};
    {
        Constructor c;
        c.name = "Lit"; c.sum_name = "expr";
        c.fields.push_back({"n", "int", FieldFlag::None});
        s.constructors["Lit"] = std::move(c);
    }
    {
        Constructor c;
        c.name = "EVar"; c.sum_name = "expr";
        c.fields.push_back({"body", "stmt", FieldFlag::None});
        s.constructors["EVar"] = std::move(c);
    }
    {
        Constructor c;
        c.name = "SExpr"; c.sum_name = "stmt";
        c.fields.push_back({"e", "expr", FieldFlag::None});
        s.constructors["SExpr"] = std::move(c);
    }
    {
        Constructor c;
        c.name = "SSeq"; c.sum_name = "stmt";
        c.fields.push_back({"next", "stmt", FieldFlag::None});
        s.constructors["SSeq"] = std::move(c);
    }
    return s;
}

} // namespace

TEST(Codegen, MultiSumDispatch) {
    // Two source-AST sums with cross-sum recursion. The emitter must
    // produce two `compile_<sum>` functions, forward-declare both, and
    // dispatch each `gen()` to the correct compile_<sum> based on the
    // subject's inferred type (left of EVar is `stmt`, e of SExpr is
    // `expr`, etc.).
    static const char* src = R"(
COMPILER twosum

IMPORTS
  ast = "ast.json"

DESTINATIONS
  data_dest delta { effect }
  ctrl_dest gamma { fail }
  ir_root int

AUXILIARIES
  cg_lit  : (int) -> int
  cg_evar : (int) -> int
  cg_sexpr : (int) -> int
  cg_sseq  : (int) -> int

RULES

rule lit  : ast.Lit(n: x)        { cg_lit(x); }
rule evar : ast.EVar(body: b)    { let k = gen(b, effect, fail); cg_evar(k); }
rule sex  : ast.SExpr(e: e)      { let k = gen(e, effect, fail); cg_sexpr(k); }
rule sseq : ast.SSeq(next: n)    { let k = gen(n, effect, fail); cg_sseq(k); }
)";
    auto* file = parse_ddcg(src);
    ASSERT_NE(file, nullptr);
    std::map<std::string, Schema> schemas{{"ast", make_two_sum_schema()}};
    auto check = check_file(file, schemas);
    ASSERT_TRUE(check.ok())
        << (check.errors.empty() ? "" : check.errors.front().message);

    std::ostringstream out;
    std::vector<std::string> emit_errs;
    ASSERT_TRUE(emit_cpp(file, schemas, check, out, emit_errs))
        << (emit_errs.empty() ? "" : emit_errs.front());
    std::string text = out.str();

    // Two dispatch methods on the class.
    EXPECT_NE(text.find("int compile_expr("), std::string::npos);
    EXPECT_NE(text.find("int compile_stmt("), std::string::npos);

    // Cross-sum gen calls dispatch by the subject's inferred sum:
    //   evar's `b` is stmt → compile_stmt
    //   sex's  `e` is expr → compile_expr
    EXPECT_NE(text.find("compile_stmt(b,"), std::string::npos)
        << "EVar.body : stmt should dispatch to compile_stmt\n" << text;
    EXPECT_NE(text.find("compile_expr(e,"), std::string::npos)
        << "SExpr.e : expr should dispatch to compile_expr\n" << text;

    // δ + γ types both derived from the .ddcg's DESTINATIONS — the
    // dispatcher signature follows the paper's CG : E → ρ → δ → γ → Code,
    // with ρ folded into the class itself.
    EXPECT_NE(text.find("delta_t d, gamma_t g)"), std::string::npos)
        << "dispatcher should take both δ and γ:\n" << text;
}

TEST(Codegen, GenCallReturnTypePropagatesToLet) {
    // `let k = gen(...)` should be declared with the ir_root type
    // (`int` here), not `auto`. Verifies the type-checker's side-table
    // flows through to let-statement emission.
    static const char* src = R"(
COMPILER hello
IMPORTS
  ast = "ast.json"
DESTINATIONS
  data_dest delta { effect }
  ctrl_dest gamma { fail }
  ir_root int
AUXILIARIES
  cg_x : (int) -> int
RULES
rule lit : ast.Lit(n: x) { cg_x(x); }
rule add : ast.Add(left: l, right: r) {
    let lk = gen(l, effect, fail);
    cg_x(lk);
}
)";
    auto* file = parse_ddcg(src);
    ASSERT_NE(file, nullptr);
    std::map<std::string, Schema> schemas{{"ast", make_tiny_schema()}};
    auto check = check_file(file, schemas);
    ASSERT_TRUE(check.ok());

    std::ostringstream out;
    std::vector<std::string> emit_errs;
    ASSERT_TRUE(emit_cpp(file, schemas, check, out, emit_errs));
    std::string text = out.str();

    // The let should be `int lk = ...`, not `auto lk = ...`.
    EXPECT_NE(text.find("int lk = compile_expr"), std::string::npos)
        << "let lk should be typed as int (ir_root), got:\n" << text;
}

