TEST(Codegen, EmptyListAnnotationContextualisesElemType) {
    // The accumulator pattern: `let xs: list<int> = []` followed by
    // `xs := xs + [item]` in a for-loop. Without the typed-bind hook,
    // `[]` infers as `list<?>` and the C++ backend can't pick an
    // element type. The typechecker contextualises empty lists when
    // the bind annotates a concrete list type, so codegen emits
    // `std::vector<int>{}`.
    static const char* src = R"(
COMPILER hello
IMPORTS
  ast = "ast.json"
DESTINATIONS
  data_dest delta { effect }
  ctrl_dest gamma { fail }
  ir_root int
AUXILIARIES
  cg_use : (int) -> int
RULES
rule lit : ast.Lit(n: x) {
    let xs: list<int> = [];
    cg_use(x);
}
rule add : ast.Add(left: l, right: r) {
    let lk = gen(l, effect, fail);
    cg_use(lk);
}
)";
    auto* file = parse_ddcg(src);
    ASSERT_NE(file, nullptr);
    std::map<std::string, Schema> schemas{{"ast", make_tiny_schema()}};
    auto check = check_file(file, schemas);
    ASSERT_TRUE(check.ok())
        << (check.errors.empty() ? "" : check.errors.front().message);

    std::ostringstream out;
    std::vector<std::string> emit_errs;
    ASSERT_TRUE(emit_cpp(file, schemas, check, out, emit_errs));
    std::string text = out.str();

    // The annotated empty list should emit a typed vector, not the
    // bare `std::vector{}` (which won't compile for empty literals).
    EXPECT_NE(text.find("std::vector<int>{}"), std::string::npos)
        << "expected std::vector<int>{} for typed empty list, got:\n" << text;
}

